using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;
public static class TextureV8Import {
 const string Root="E:/personalProject/Demo3/demo6/아트/텍스처-구조-v8";
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");if(!Application.dataPath.Contains("texture-v8-review-isolated"))throw new Exception("Export only in owned isolated project");var rows=new List<object>();foreach(var p in JArray.Parse(File.ReadAllText(Root+"/manifest.json"))){string id=(string)p["id"];int w=(int)p["width"],h=(int)p["height"],n=4;byte[] b=File.ReadAllBytes(Root+"/layers/"+id+"/composite.rgba");var colors=new Color32[w*h/n/n];for(int y=0;y<h/n;y++)for(int x=0;x<w/n;x++){int r=0,g=0,bl=0;for(int j=0;j<n;j++)for(int i=0;i<n;i++){int at=((h-1-y*n-j)*w+x*n+i)*4;r+=b[at];g+=b[at+1];bl+=b[at+2];if(b[at+3]!=255)throw new Exception("Environment alpha must stay opaque");}colors[y*w/n+x]=new Color32((byte)((r+8)/16),(byte)((g+8)/16),(byte)((bl+8)/16),255);}var tex=new Texture2D(w/n,h/n,TextureFormat.RGBA32,false);tex.SetPixels32(colors);tex.Apply();var png=tex.EncodeToPNG();string path=(string)p["runtimePath"];File.WriteAllBytes(Root+"/runtime-PNG/"+id+".png",png);File.WriteAllBytes(path,png);UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);var importer=(TextureImporter)AssetImporter.GetAtPath(path);rows.Add(new{id,width=w/n,height=h/n,ppu=importer.spritePixelsPerUnit,readable=importer.isReadable,mipmap=importer.mipmapEnabled,filter=importer.filterMode.ToString(),runtimePath=path});}File.WriteAllText(Root+"/export-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));return rows;}
}
